7.1.1 Fresnel coefficients, live


Show the Python
viewof fr = Inputs.form({
  n1: Inputs.range([1, 4], {value: 1.44, step: 0.01, label: "incidence medium n₁"}),
  n2: Inputs.range([1, 4], {value: 1.00, step: 0.01, label: "second medium n₂"}),
  show: Inputs.radio(["|r| (amplitude)", "R, T (power)", "phase of r"], {value: "|r| (amplitude)", label: "show"})
})









Show the Python
frData = {
  // small complex helpers
  const C = (re, im = 0) =&gt; ({re, im});
  const add = (a, b) =&gt; C(a.re + b.re, a.im + b.im), sub = (a, b) =&gt; C(a.re - b.re, a.im - b.im);
  const mul = (a, b) =&gt; C(a.re*b.re - a.im*b.im, a.re*b.im + a.im*b.re);
  const div = (a, b) =&gt; { const d = b.re*b.re + b.im*b.im; return C((a.re*b.re + a.im*b.im)/d, (a.im*b.re - a.re*b.im)/d); };
  const abs = a =&gt; Math.hypot(a.re, a.im), arg = a =&gt; Math.atan2(a.im, a.re) * 180 / Math.PI;
  const n = fr.n2 / fr.n1, out = [];
  for (let deg = 0; deg &lt;= 89.9; deg += 0.1) {
    const t = deg * Math.PI / 180, ci = C(Math.cos(t)), x = n*n - Math.sin(t)**2;
    const s = x &gt;= 0 ? C(Math.sqrt(x)) : C(0, -Math.sqrt(-x));        // Im ≤ 0 branch
    const n2c = C(n*n*Math.cos(t));
    const rs = div(sub(ci, s), add(ci, s)), rp = div(sub(s, n2c), add(s, n2c));
    const Rs = abs(rs)**2, Rp = abs(rp)**2;
    out.push({deg, v: abs(rs), q: "r⊥"}, {deg, v: abs(rp), q: "r∥"},
             {deg, v: Rs, q: "R⊥"}, {deg, v: Rp, q: "R∥"}, {deg, v: 1 - Rs, q: "T⊥"}, {deg, v: 1 - Rp, q: "T∥"},
             {deg, v: arg(rs), q: "φ⊥"}, {deg, v: arg(rp), q: "φ∥"});
  }
  return out;
}
{
  const keys = fr.show.startsWith("|r|") ? ["r⊥", "r∥"] : fr.show.startsWith("R") ? ["R⊥", "R∥", "T⊥", "T∥"] : ["φ⊥", "φ∥"];
  const thp = Math.atan(fr.n2 / fr.n1) * 180 / Math.PI, thc = fr.n1 &gt; fr.n2 ? Math.asin(fr.n2 / fr.n1) * 180 / Math.PI : null;
